import{_ as e,o as s,c as t,a5 as i}from"./chunks/framework.a5no_H3L.js";const k=JSON.parse('{"title":"常见场景与上线检查","description":"本文两部分：Kafka 的典型应用场景索引，以及首次生产部署的上线检查清单。清单的重点不是参数罗列，而是每个关键项「为什么这么设」——复制配置前先理解取舍，否则场景变化时无法自行调整。","frontmatter":{},"headers":[],"relativePath":"kafka/10-practice/chapter-03-common-patterns.md","filePath":"kafka/10-practice/chapter-03-common-patterns.md"}'),n={name:"kafka/10-practice/chapter-03-common-patterns.md"};function c(r,a,l,p,d,o){return s(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="常见场景与上线检查" tabindex="-1" data-src-line="1" data-src-file="kafka/10-practice/chapter-03-common-patterns.md">常见场景与上线检查 <a class="header-anchor" href="#常见场景与上线检查" aria-label="Permalink to &quot;常见场景与上线检查&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="kafka/10-practice/chapter-03-common-patterns.md"><p data-src-line="3" data-src-file="kafka/10-practice/chapter-03-common-patterns.md">本文两部分：Kafka 的典型应用场景索引，以及首次生产部署的上线检查清单。清单的重点不是参数罗列，而是每个关键项「为什么这么设」——复制配置前先理解取舍，否则场景变化时无法自行调整。</p></blockquote><h2 id="_1-日志收集" tabindex="-1" data-src-line="5" data-src-file="kafka/10-practice/chapter-03-common-patterns.md">1. 日志收集 <a class="header-anchor" href="#_1-日志收集" aria-label="Permalink to &quot;1. 日志收集&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>App → Kafka → Logstash → Elasticsearch → Kibana</span></span></code></pre></div><h2 id="_2-事件驱动架构" tabindex="-1" data-src-line="11" data-src-file="kafka/10-practice/chapter-03-common-patterns.md">2. 事件驱动架构 <a class="header-anchor" href="#_2-事件驱动架构" aria-label="Permalink to &quot;2. 事件驱动架构&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Service A → Kafka → Service B</span></span>
<span class="line"><span>                → Service C</span></span>
<span class="line"><span>                → Service D</span></span></code></pre></div><p data-src-line="19" data-src-file="kafka/10-practice/chapter-03-common-patterns.md">多个消费者可组成同一个消费者组分担分区，也可用不同的消费者组各自独立消费同一份事件流，具体语义取决于 Topic、分区和消费者组配置。服务间通信的通用模式（竞争消费者、发布订阅等）见 <a href="./../../scenarios/03-messaging/chapter-02-messaging-patterns.html">消息模式综述</a>。</p><h2 id="_3-数据管道" tabindex="-1" data-src-line="21" data-src-file="kafka/10-practice/chapter-03-common-patterns.md">3. 数据管道 <a class="header-anchor" href="#_3-数据管道" aria-label="Permalink to &quot;3. 数据管道&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MySQL → Debezium → Kafka → Elasticsearch</span></span>
<span class="line"><span>                        → Data Warehouse</span></span></code></pre></div><p data-src-line="28" data-src-file="kafka/10-practice/chapter-03-common-patterns.md">Source / Sink 的接入与配置见 <a href="./../09-connect/chapter-01-connect-basics.html">Kafka Connect 概览</a>。</p><h2 id="_4-流式处理" tabindex="-1" data-src-line="30" data-src-file="kafka/10-practice/chapter-03-common-patterns.md">4. 流式处理 <a class="header-anchor" href="#_4-流式处理" aria-label="Permalink to &quot;4. 流式处理&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Kafka → Kafka Streams/Flink → Kafka</span></span></code></pre></div><p data-src-line="36" data-src-file="kafka/10-practice/chapter-03-common-patterns.md">Kafka Streams 的定位与核心抽象见 <a href="./../08-streams/chapter-01-streams-basics.html">Kafka Streams 概览</a>。</p><h2 id="_5-指标监控" tabindex="-1" data-src-line="38" data-src-file="kafka/10-practice/chapter-03-common-patterns.md">5. 指标监控 <a class="header-anchor" href="#_5-指标监控" aria-label="Permalink to &quot;5. 指标监控&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Kafka Broker / JMX → 指标导出器 → Prometheus → Grafana</span></span></code></pre></div><p data-src-line="44" data-src-file="kafka/10-practice/chapter-03-common-patterns.md">集群侧指标采集与告警配置见 <a href="./../06-operations/chapter-01-monitoring.html">监控</a>。</p><h2 id="_6-上线检查清单" tabindex="-1" data-src-line="46" data-src-file="kafka/10-practice/chapter-03-common-patterns.md">6. 上线检查清单 <a class="header-anchor" href="#_6-上线检查清单" aria-label="Permalink to &quot;6. 上线检查清单&quot;">​</a></h2><p data-src-line="48" data-src-file="kafka/10-practice/chapter-03-common-patterns.md">本清单用于首次部署前的检查，不替代容量规划和生产压测。以下配置值用于说明关键参数的作用，实际取值应结合目标 Kafka 版本、部署模式、消息吞吐量、数据保留要求和故障恢复目标确定。</p><h3 id="_6-1-硬件规划" tabindex="-1" data-src-line="50" data-src-file="kafka/10-practice/chapter-03-common-patterns.md">6.1 硬件规划 <a class="header-anchor" href="#_6-1-硬件规划" aria-label="Permalink to &quot;6.1 硬件规划&quot;">​</a></h3><table tabindex="0"><thead data-src-line="52" data-src-file="kafka/10-practice/chapter-03-common-patterns.md"><tr data-src-line="52" data-src-file="kafka/10-practice/chapter-03-common-patterns.md"><th style="text-align:left;">组件</th><th style="text-align:left;">示例起点</th></tr></thead><tbody data-src-line="54" data-src-file="kafka/10-practice/chapter-03-common-patterns.md"><tr data-src-line="54" data-src-file="kafka/10-practice/chapter-03-common-patterns.md"><td style="text-align:left;">内存</td><td style="text-align:left;">≥ 32G</td></tr><tr data-src-line="55" data-src-file="kafka/10-practice/chapter-03-common-patterns.md"><td style="text-align:left;">磁盘</td><td style="text-align:left;">多块 SSD/HDD，JBOD 或 RAID 10</td></tr><tr data-src-line="56" data-src-file="kafka/10-practice/chapter-03-common-patterns.md"><td style="text-align:left;">CPU</td><td style="text-align:left;">≥ 8 核</td></tr><tr data-src-line="57" data-src-file="kafka/10-practice/chapter-03-common-patterns.md"><td style="text-align:left;">网络</td><td style="text-align:left;">万兆网卡（高吞吐场景）</td></tr></tbody></table><p data-src-line="59" data-src-file="kafka/10-practice/chapter-03-common-patterns.md">内存这一项最容易配错。Kafka 的消息数据放在操作系统页缓存里，不在 JVM 堆内，所以「内存越大越好」不是指给 JVM，而是优先给页缓存留出空间。下面公式是规划示意，不是严格的内存分配等式，实际页缓存由操作系统按可用内存动态管理：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>总内存 = JVM 堆（示例 6G） + 页缓存 + 堆外内存与系统开销</span></span></code></pre></div><p data-src-line="65" data-src-file="kafka/10-practice/chapter-03-common-patterns.md">JVM 堆承载请求处理、对象分配等运行时数据，网络缓冲区等则多位于堆外内存。页缓存是吞吐量的重要基础，热点数据留在页缓存里，读取不落盘。页缓存为什么是高吞吐的基础，见 <a href="./../04-performance/chapter-01-why-kafka-is-fast.html">为什么 Kafka 这么快</a>。32G 机器堆给 6G 只是示例起点，剩余内存要在页缓存、堆外内存和系统服务之间分配，不能认定全部交给页缓存。</p><p data-src-line="67" data-src-file="kafka/10-practice/chapter-03-common-patterns.md">磁盘选 JBOD（多块独立盘）还是 RAID 10，取决于故障恢复要求和运维能力，不是非此即彼。Kafka 副本分布在不同 Broker 上，提供跨节点的数据冗余；RAID 10 保护的是单机磁盘故障，两者机制不同。JBOD 是常见选择，但需考虑单盘故障后的分区恢复和容量不均衡，不能仅凭「副本已提供冗余」就排除 RAID。</p><h3 id="_6-2-broker-关键配置" tabindex="-1" data-src-line="69" data-src-file="kafka/10-practice/chapter-03-common-patterns.md">6.2 Broker 关键配置 <a class="header-anchor" href="#_6-2-broker-关键配置" aria-label="Permalink to &quot;6.2 Broker 关键配置&quot;">​</a></h3><p data-src-line="71" data-src-file="kafka/10-practice/chapter-03-common-patterns.md">下面配置用于展示关键配置项及其相互关系，不是可直接复制到任意生产集群的完整模板。参数可分成三类：可靠性策略（副本数、最小 ISR、不干净 Leader 选举）、容量与保留策略（日志目录、分区数、保留时长）、性能调优项（网络线程、Socket 缓冲、复制抓取参数）。分区数、线程数等取值需按目标版本、硬件和实际负载验证。</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 身份</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">broker.id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=1  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 每个节点不同</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 监听</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">listeners</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=PLAINTEXT://0.0.0.0:9092</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">advertised.listeners</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=PLAINTEXT://broker1:9092</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 日志</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">log.dirs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=/data1/kafka-logs,/data2/kafka-logs</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">num.partitions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=6</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">default.replication.factor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=3</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">min.insync.replicas</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=2</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">unclean.leader.election.enable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=false</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">log.retention.hours</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=168</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">log.segment.bytes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=1073741824</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 网络</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">num.network.threads</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=8</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">num.io.threads</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=16</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">socket.send.buffer.bytes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=102400</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">socket.receive.buffer.bytes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=102400</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">socket.request.max.bytes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=104857600</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 副本</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">replica.fetch.max.bytes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=10485760</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">replica.fetch.wait.max.ms</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=500</span></span></code></pre></div><p data-src-line="102" data-src-file="kafka/10-practice/chapter-03-common-patterns.md">重点项的取舍：</p><ul data-src-line="104" data-src-file="kafka/10-practice/chapter-03-common-patterns.md"><li data-src-line="104" data-src-file="kafka/10-practice/chapter-03-common-patterns.md"><code>listeners</code> 与 <code>advertised.listeners</code>：前者是 Broker 实际监听的地址（本机 <code>0.0.0.0</code>），后者是返回给客户端的地址（客户端可解析的 <code>broker1</code>）。两者为什么分离、配错会怎样，见<a href="./chapter-01-first-app.html#prepare-local-env">准备本地环境</a>。示例用 <code>PLAINTEXT</code> 仅用于可信网络内的演示与连通性验证，生产环境应按要求配置 TLS、SASL 等认证机制，并限制 Broker 端口网络访问范围。</li><li data-src-line="105" data-src-file="kafka/10-practice/chapter-03-common-patterns.md"><code>log.dirs</code> 多个目录：让 Kafka 把不同分区的日志存到不同目录，为多盘并行 I/O 提供条件。实际负载分布取决于分区分配和各目录容量、写入速率，不能假定所有磁盘始终均匀工作。</li><li data-src-line="106" data-src-file="kafka/10-practice/chapter-03-common-patterns.md"><code>min.insync.replicas=2</code> + <code>acks=all</code>：<code>acks=all</code> 要求写入时 ISR 中的副本完成确认；<code>min.insync.replicas=2</code> 要求接受写入时 ISR 至少包含 2 个副本。若 ISR 因故障少于 2 个，Broker 会拒绝写入（如 <code>NotEnoughReplicasException</code> 或 <code>NotEnoughReplicasAfterAppend</code>），而不是在副本不足时继续接受。这组配置提高了写入的复制保障，但不等于数据已通过 fsync 刷入所有物理磁盘，也不能替代备份和故障恢复演练。完整机制见 <a href="./../02-core/chapter-05-ack-and-idempotence.html">ACK 与幂等</a>。</li><li data-src-line="107" data-src-file="kafka/10-practice/chapter-03-common-patterns.md"><code>unclean.leader.election.enable=false</code>：禁止把 ISR 之外的副本作为最后手段选为 Leader。这可以避免因选中 ISR 之外的副本而丢失它尚未同步的消息，但当 ISR 中没有可用候选者时，分区可能暂时无法写入。该配置降低了一类数据丢失风险，不构成绝对的数据不丢失保证。ISR 机制见 <a href="./../02-core/chapter-04-replication-and-isr.html">副本与 ISR</a>。</li><li data-src-line="108" data-src-file="kafka/10-practice/chapter-03-common-patterns.md"><code>num.partitions=6</code>：未显式指定分区数的新 Topic 的默认分区数。分区数影响该 Topic 的分区级并行能力，但分区越多不等于吞吐量越高，还需考虑消费者组规模、Broker 资源和分区管理开销，规划方法见 <a href="./../04-performance/chapter-03-partition-sizing.html">分区数选择</a>。</li><li data-src-line="109" data-src-file="kafka/10-practice/chapter-03-common-patterns.md"><code>replica.fetch.max.bytes=10485760</code>：控制副本单次拉取数据的目标上限，配置较小时大批次复制可能需要更多轮拉取。它与 <code>socket.request.max.bytes</code> 不是同一限制，规划时应同时核对 Topic 的消息大小限制、生产者请求大小和消费者拉取限制，不要仅凭数值大小判断消息是否可被复制或消费。</li></ul><h3 id="_6-3-jvm-配置" tabindex="-1" data-src-line="111" data-src-file="kafka/10-practice/chapter-03-common-patterns.md">6.3 JVM 配置 <a class="header-anchor" href="#_6-3-jvm-配置" aria-label="Permalink to &quot;6.3 JVM 配置&quot;">​</a></h3><p data-src-line="113" data-src-file="kafka/10-practice/chapter-03-common-patterns.md">下面配置可作为测试环境的起点，生产环境需结合堆使用情况和 GC 日志调整：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> KAFKA_HEAP_OPTS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-Xms6g -Xmx6g -XX:+UseG1GC&quot;</span></span></code></pre></div><ul data-src-line="119" data-src-file="kafka/10-practice/chapter-03-common-patterns.md"><li data-src-line="119" data-src-file="kafka/10-practice/chapter-03-common-patterns.md"><code>-Xms6g -Xmx6g</code>：初始堆等于最大堆，避免运行中堆容量动态扩展。堆设 6G 而非 32G，理由见 §6.1，数据在页缓存，堆大了反而挤压页缓存空间；但 6G 只是示例，需按实际负载验证。</li><li data-src-line="120" data-src-file="kafka/10-practice/chapter-03-common-patterns.md"><code>-XX:+UseG1GC</code>：G1 支持按目标停顿时间进行调优，适合 Kafka 这种对延迟敏感、对象生命周期不一的场景，但不能保证每次停顿都满足目标。</li><li data-src-line="121" data-src-file="kafka/10-practice/chapter-03-common-patterns.md"><code>-XX:MaxGCPauseMillis</code>：可选，用于设置停顿时间目标。它是调优目标而非硬性上限，20ms 这类具体值需结合 GC 日志和压测确定，仅在必要时调整。</li></ul><h3 id="_6-4-监控接入" tabindex="-1" data-src-line="123" data-src-file="kafka/10-practice/chapter-03-common-patterns.md">6.4 监控接入 <a class="header-anchor" href="#_6-4-监控接入" aria-label="Permalink to &quot;6.4 监控接入&quot;">​</a></h3><p data-src-line="125" data-src-file="kafka/10-practice/chapter-03-common-patterns.md">上线前应确认监控采集、告警规则和通知链路均已验证，至少覆盖副本健康、消费积压、Broker 资源使用和请求处理四类信号。其中两条最需要优先告警：</p><ul data-src-line="127" data-src-file="kafka/10-practice/chapter-03-common-patterns.md"><li data-src-line="127" data-src-file="kafka/10-practice/chapter-03-common-patterns.md"><code>UnderReplicatedPartitions</code> 持续大于 0：存在副本未达到预期同步状态。应结合持续时间、ISR 变化和 Broker 健康状态判断是否告警，滚动升级或副本迁移期间短暂出现不一定意味着故障扩大；若指标持续不恢复或同时出现 ISR 缩减，应提高告警级别并排查副本复制问题。</li><li data-src-line="128" data-src-file="kafka/10-practice/chapter-03-common-patterns.md">Consumer Lag 持续增长：消费速度跟不上生产，积压在扩大。告警应关注持续时间和变化趋势，避免仅凭单次指标波动判断。</li></ul><p data-src-line="130" data-src-file="kafka/10-practice/chapter-03-common-patterns.md">其余核心指标与告警阈值见 <a href="./../06-operations/chapter-01-monitoring.html">监控</a>；Lag 的排查步骤见 <a href="./../05-troubleshooting/chapter-01-consumer-lag.html">消费者 Lag 过大</a>。</p>`,37)])])}const m=e(n,[["render",c]]);export{k as __pageData,m as default};
